using System;using System.IO;using System.Linq;using UnityEngine;using UnityEngine.UI;using UnityEditor;using UnityEditor.SceneManagement;using IdleIntelligence.Runtime;
namespace IdleIntelligence.Editor {
 public static class RefinePresentation {
  const string Root="Assets/IdleIntelligence/";const string Fx=Root+"Resources/PixelUI/";
  static void SaveAsset(UnityEngine.Object value,string path){var old=AssetDatabase.LoadMainAssetAtPath(path);if(old==null)AssetDatabase.CreateAsset(value,path);else{EditorUtility.CopySerialized(value,old);UnityEngine.Object.DestroyImmediate(value);}}
  static void At(RectTransform r,Vector2 anchor,Vector2 size){r.anchorMin=r.anchorMax=anchor;r.pivot=new Vector2(.5f,.5f);r.anchoredPosition=Vector2.zero;r.sizeDelta=size;}
  public static void Build(){BuildForgeSequence.Build();EditorSceneManager.OpenScene("Assets/Scenes/IdleIntelligence.unity");var game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();var safe=game.GetComponent<MobileShell>().Laboratory.GetComponentInParent<SafeArea>().transform;var header=safe.Find("Header");if(header.Find("Menu")==null){var menu=WorkshopUIFactory.Button("Menu",header,"",null);var size=menu.GetComponent<LayoutElement>();size.minWidth=size.preferredWidth=54;size.flexibleWidth=0;menu.GetComponent<Image>().sprite=null;menu.GetComponent<Image>().color=Color.clear;var icon=WorkshopUIFactory.Node("Hamburger",menu.transform,typeof(CompactGlyph)).GetComponent<CompactGlyph>();icon.Kind=CompactGlyph.Symbol.Menu;icon.raycastTarget=false;icon.color=GameTheme.Text;At(icon.rectTransform,new Vector2(.5f,.5f),new Vector2(27,27));}
   var cell=safe.Find("Resources/ResourceCell3");cell.Find("ResourceName").GetComponent<Text>().text="Gems";var atlas=game.GetComponent<MobileShell>().ResourceIcons[0].texture;var gem=Sprite.Create(atlas,new Rect(atlas.width/4f,atlas.height/2f,atlas.width/4f,atlas.height/2f),new Vector2(.5f,.5f),100,0,SpriteMeshType.FullRect);gem.name="ui-gem";SaveAsset(gem,Fx+"gem.asset");cell.Find("ResourceIcon").GetComponent<Image>().sprite=AssetDatabase.LoadAssetAtPath<Sprite>(Fx+"gem.asset");
   var modelImporter=(TextureImporter)AssetImporter.GetAtPath(AssetDatabase.GetAssetPath(game.ModelPrefab.ModelArt));modelImporter.filterMode=FilterMode.Point;modelImporter.mipmapEnabled=false;modelImporter.SaveAndReimport();
   var loadout=WorkshopUIFactory.Vertical("ModelLoadout",null);var view=loadout.AddComponent<ModelLoadout>();var network=WorkshopUIFactory.Node("ModelNetwork",loadout.transform,typeof(LayoutElement));network.GetComponent<LayoutElement>().minHeight=network.GetComponent<LayoutElement>().preferredHeight=320;view.Network=(RectTransform)network.transform;
   var links=WorkshopUIFactory.Node("ModelConnections",network.transform,typeof(ModelLinks));WorkshopUIFactory.Fill((RectTransform)links.transform);links.GetComponent<ModelLinks>().raycastTarget=false;view.Core=WorkshopUIFactory.Node("OriginalModelCore",network.transform,typeof(Image)).GetComponent<Image>();view.Core.sprite=game.ModelPrefab.ModelArt;view.Core.preserveAspect=true;view.Core.raycastTarget=false;At(view.Core.rectTransform,new Vector2(.5f,.5f),new Vector2(124,124));view.Name=WorkshopUIFactory.Label("ModelName",network.transform,"",12);UnityEngine.Object.DestroyImmediate(view.Name.GetComponent<LayoutElement>());At(view.Name.rectTransform,new Vector2(.5f,.29f),new Vector2(150,22));view.Name.alignment=TextAnchor.MiddleCenter;view.Name.font=GameTheme.Bold;
   var universal=WorkshopUIFactory.Horizontal("UniversalSockets",loadout.transform,54);universal.GetComponent<HorizontalLayoutGroup>().childForceExpandWidth=false;universal.GetComponent<HorizontalLayoutGroup>().childAlignment=TextAnchor.MiddleCenter;view.Universal=(RectTransform)universal.transform;view.Stats=WorkshopUIFactory.Label("ModelStats",loadout.transform,"",12,42);view.Stats.alignment=TextAnchor.MiddleCenter;PrefabUtility.SaveAsPrefabAsset(loadout,Fx+"ModelLoadout.prefab");UnityEngine.Object.DestroyImmediate(loadout);
   var metrics=ScriptableObject.CreateInstance<ItemArtMetrics>();metrics.Sprites=game.WorkshopPrefab.ItemSprites;metrics.AlphaRects=new Rect[metrics.Sprites.Length];var textures=new System.Collections.Generic.Dictionary<string,Texture2D>();for(int i=0;i<metrics.Sprites.Length;i++){var sprite=metrics.Sprites[i];string path=AssetDatabase.GetAssetPath(sprite.texture);if(!textures.TryGetValue(path,out var texture)){texture=new Texture2D(2,2);texture.LoadImage(File.ReadAllBytes(path));textures.Add(path,texture);}float ratioX=(float)texture.width/sprite.texture.width,ratioY=(float)texture.height/sprite.texture.height;var rect=sprite.rect;int x0=Mathf.RoundToInt(rect.x*ratioX),y0=Mathf.RoundToInt(rect.y*ratioY),width=Mathf.RoundToInt(rect.width*ratioX),height=Mathf.RoundToInt(rect.height*ratioY);int left=width,right=0,bottom=height,top=0;for(int y=0;y<height;y++)for(int x=0;x<width;x++)if(texture.GetPixel(x0+x,y0+y).a>.5f){left=Math.Min(left,x);right=Math.Max(right,x);bottom=Math.Min(bottom,y);top=Math.Max(top,y);}metrics.AlphaRects[i]=left<=right?new Rect((float)left/width,(float)bottom/height,(float)(right-left+1)/width,(float)(top-bottom+1)/height):new Rect(0,0,1,1);}
   foreach(var texture in textures.Values)UnityEngine.Object.DestroyImmediate(texture);SaveAsset(metrics,Fx+"ItemArtMetrics.asset");foreach(string name in new[]{"Header","Resources"}){var t=safe.Find(name);if(PrefabUtility.IsPartOfPrefabInstance(t))PrefabUtility.ApplyPrefabInstance(t.gameObject,InteractionMode.AutomatedAction);}EditorSceneManager.SaveScene(game.gameObject.scene);AssetDatabase.SaveAssets();Debug.Log("PRESENTATION_REFINED gem from actual atlas; menu existing routes; TS model network; alpha metrics for "+game.WorkshopPrefab.ItemSprites.Length+" original items");
  }
 }
}
